// FilterBar provides month, year, and distributor filter dropdowns.
// Props:
//   filters      — { month, year, distributor }
//   onChange     — (filters) => void
//   distributors — string[] list of available distributor names

const MONTHS = [
  "January","February","March","April","May","June",
  "July","August","September","October","November","December",
];

const currentYear = new Date().getFullYear();
const YEARS = Array.from({ length: 4 }, (_, i) => currentYear - i);

export default function FilterBar({ filters = {}, onChange, distributors = [] }) {
  const update = (key, value) => onChange({ ...filters, [key]: value });

  return (
    <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <i className="ti ti-calendar" style={{ fontSize: 15, color: "var(--color-text-secondary)" }} aria-hidden />
        <select value={filters.month || ""} onChange={(e) => update("month", e.target.value)}>
          <option value="">All months</option>
          {MONTHS.map((m) => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      <select value={filters.year || ""} onChange={(e) => update("year", e.target.value)}>
        <option value="">All years</option>
        {YEARS.map((y) => <option key={y} value={y}>{y}</option>)}
      </select>

      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        <i className="ti ti-truck" style={{ fontSize: 15, color: "var(--color-text-secondary)" }} aria-hidden />
        <select value={filters.distributor || ""} onChange={(e) => update("distributor", e.target.value)}>
          <option value="">All distributors</option>
          {distributors.map((d) => <option key={d} value={d}>{d}</option>)}
        </select>
      </div>

      {(filters.month || filters.year || filters.distributor) && (
        <button
          onClick={() => onChange({ month: "", year: "", distributor: "" })}
          style={{ fontSize: 12, display: "flex", alignItems: "center", gap: 4, color: "var(--color-text-secondary)" }}
        >
          <i className="ti ti-x" style={{ fontSize: 13 }} aria-hidden /> Clear filters
        </button>
      )}
    </div>
  );
}
